counterexample:
-- Insert data for a counterexample where Q1 and Q2 differ

-- Insert Bar
INSERT INTO Bar (name, address) VALUES ('Bar1', '123 Main St');

-- Insert Beers
INSERT INTO Beer (name, brewer) VALUES ('Beer1', 'BrewerA');
INSERT INTO Beer (name, brewer) VALUES ('Beer2', 'BrewerB');

-- Insert Drinker
INSERT INTO Drinker (name, address) VALUES ('Alice', '456 Elm St');

-- Insert Frequents: Alice frequents Bar1
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'Bar1', 3);

-- Insert Serves: Bar1 serves two beers
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Beer1', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Beer2', 5.50);

-- Insert Likes: Alice only likes Beer1 and not Beer2
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'Beer1');

