counterexample:
-- Insert Bars
INSERT INTO Bar (name, address) VALUES ('Bar1', 'Address1');
INSERT INTO Bar (name, address) VALUES ('Bar2', 'Address2');
INSERT INTO Bar (name, address) VALUES ('Bar3', 'Address3');

-- Insert Beers
INSERT INTO Beer (name, brewer) VALUES ('BeerX', 'BrewerA');
INSERT INTO Beer (name, brewer) VALUES ('BeerY', 'BrewerB');

-- Insert Drinkers
INSERT INTO Drinker (name, address) VALUES ('Bob', 'AddrB');
INSERT INTO Drinker (name, address) VALUES ('Bill', 'AddrBill');
INSERT INTO Drinker (name, address) VALUES ('Alice', 'AddrA');

-- Insert Frequents
-- Bar1 and Bar2 are frequented by B-drinkers
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar1', 3);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar2', 2);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bill', 'Bar2', 4);
-- Bar1 is also frequented by a B-drinker (for beerY) but that beer will appear only once
-- Bar3 is frequented by a non-B drinker
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'Bar3', 2);

-- Insert Serves
-- BeerX is served in all three bars:
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerX', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar2', 'BeerX', 10.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar3', 'BeerX', 20.00);

-- BeerY is served only in Bar1
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerY', 50.00);

