counterexample:
-- Under the schema constraints there is no valid INSERT data that makes Q1 and Q2 return different results.
-- For example, consider the following test data:

INSERT INTO Beer (name, brewer) VALUES ('IPA', 'BrewCo');
INSERT INTO Beer (name, brewer) VALUES ('Stout', 'BrewCo');

INSERT INTO Bar (name, address) VALUES ('BarA', 'AddressA');
INSERT INTO Bar (name, address) VALUES ('BarB', 'AddressB');

-- IPA is served at two bars, one at a lower price and one at a higher price
INSERT INTO Serves (bar, beer, price) VALUES ('BarA', 'IPA', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('BarB', 'IPA', 6.00);

-- Stout is not served anywhere

-- Both Q1 and Q2 will return for IPA the row with price 5.00 (and for Stout a row with NULL bar and NULL price).
-- Therefore, with this test data the outputs of Q1 and Q2 are identical.

-- Since no data obeying the schema can force a difference in behavior, no counterexample exists.

